module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg areset;
    reg in;
    wire out;

    // Instantiate DUT
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .in(in),
        .out(out)
    );

    // Clock generator (10ns period)
    always #5 clk = ~clk;

    integer errors = 0;

    // Helper task to check output
    task check_out(input expected_out, input [127:0] step_name);
        begin
            if (out !== expected_out) begin
                $display("ERROR at %0t [%0s]: expected out = %b, got %b", $time, step_name, expected_out, out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        in = 0;

        // 1. Test asynchronous reset assertion
        #2;
        areset = 1;
        #1;
        // Upon areset, state should be B, output = 1 asynchronously
        check_out(1'b1, "Async Reset Asserted");

        #10;
        // Deassert reset synchronized to clock falling edge
        @(negedge clk);
        areset = 0;
        check_out(1'b1, "State B after Reset Deasserted");

        // 2. In State B (out = 1), apply in = 1 -> should stay in B
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b1, "State B with in=1 (stay in B)");

        // 3. In State B, apply in = 0 -> transition to State A (out = 0)
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b0, "State A after B->A (in=0)");

        // 4. In State A (out = 0), apply in = 1 -> should stay in A
        @(negedge clk);
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b0, "State A with in=1 (stay in A)");

        // 5. In State A, apply in = 0 -> transition to State B (out = 1)
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b1, "State B after A->B (in=0)");

        // 6. Transition to State A again
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b0, "State A again");

        // 7. Test asynchronous reset while in State A (between clock edges)
        #2; // mid-cycle
        areset = 1;
        #1;
        check_out(1'b1, "Async Reset from State A (instant recovery to B)");

        // Release reset
        @(negedge clk);
        areset = 0;
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b1, "State B running normally after async reset");

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
